B = G["buy"]


def buy(p, agent=2.0, lawyer=1.0, rate=None):
    rate = B["tt"] if rate is None else rate
    sc = 0; lo = 0
    for hi, r in B["notary"]:
        top = min(p, hi)
        if top > lo: sc += (top - lo) * r
        if p <= hi: break
        lo = hi
    t = {"tt": p * rate, "notary": (sc + B["notary_fixed"]) * 1.24, "cad": p * B["cad"] + B["cad_fixed"], "lawyer": p * lawyer / 100 * 1.24, "agent": p * agent / 100 * 1.24}
    t["costs"] = sum(t.values()); return t


