br = G["rent"]["br"]


def gtax(gross):
    t = 0; lo = 0; x = gross * 0.95
    for hi, r in br:
        top = min(x, hi if hi else x)
        if top > lo: t += (top - lo) * r
        if hi is None or x <= hi: break
        lo = hi
    return t


