for P in (athens, acq, tax):
    io.open(os.path.join(OUT, P["slug"] + ".html"), "w", encoding="utf-8").write(P["body"])
    json.dump({k: P[k] for k in ("title", "seo_t", "seo_d", "crumb")}, io.open(os.path.join(OUT, P["slug"] + ".json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    import re
    txt = re.sub(r"<[^>]+>", " ", re.sub(r"<(style|script)[^>]*>.*?</\1>", " ", P["body"], flags=re.S))
    dash = [m for m in re.finditer(r"[–—]", txt)]
    print(P["slug"], "| words", len(re.findall(r"[\w֐-׿]+", txt)), "| bytes", len(P["body"].encode()), "| dashes", len(dash), "| seo_t", len(P["seo_t"]))
